import{_ as a,o as i,c as n,a as t}from"./app.DkoUFz-u.js";const c=JSON.parse('{"title":"Redis高级特性 学习笔记","description":"","frontmatter":{},"headers":[],"relativePath":"data/performance/caching/technologies/redis.md","filePath":"data/performance/caching/technologies/redis.md"}'),l={name:"data/performance/caching/technologies/redis.md"};function e(p,s,o,_,h,r){return i(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="redis高级特性-学习笔记" tabindex="-1">Redis高级特性 学习笔记 <a class="header-anchor" href="#redis高级特性-学习笔记" aria-label="Permalink to &quot;Redis高级特性 学习笔记&quot;">​</a></h1><blockquote><p>数据库层开发 → 高性能访问 → 缓存策略 → 缓存技术 → Redis高级特性</p></blockquote><h2 id="一、redis概述与核心优势" tabindex="-1">一、Redis概述与核心优势 <a class="header-anchor" href="#一、redis概述与核心优势" aria-label="Permalink to &quot;一、Redis概述与核心优势&quot;">​</a></h2><p>Redis（Remote Dictionary Server）是一款基于ANSI C语言开发的开源内存数据库，其设计初衷是解决传统关系型数据库在高并发场景下的性能瓶颈。</p><p><strong>核心优势</strong>：</p><table tabindex="0"><thead><tr><th>优势</th><th>说明</th></tr></thead><tbody><tr><td>超高性能</td><td>单机每秒可处理数十万次请求，响应时间微秒级</td></tr><tr><td>丰富数据结构</td><td>支持String、Hash、List、Set、ZSet等原生数据结构</td></tr><tr><td>持久化机制</td><td>提供RDB和AOF两种方式，平衡数据安全性和性能</td></tr><tr><td>高可用架构</td><td>支持主从复制、哨兵模式和集群部署</td></tr><tr><td>多功能性</td><td>缓存、消息队列、分布式锁、限流、排行榜等</td></tr></tbody></table><p><strong>典型应用场景</strong>：热点数据缓存（电商商品详情、用户会话）、计数器与排行榜（销量统计、积分排名）、分布式锁、消息队列、限流与熔断等。</p><h2 id="二、缓存策略" tabindex="-1">二、缓存策略 <a class="header-anchor" href="#二、缓存策略" aria-label="Permalink to &quot;二、缓存策略&quot;">​</a></h2><p>缓存策略是指在缓存系统中管理数据存储和失效的规则。</p><h3 id="_2-1-内存淘汰策略" tabindex="-1">2.1 内存淘汰策略 <a class="header-anchor" href="#_2-1-内存淘汰策略" aria-label="Permalink to &quot;2.1 内存淘汰策略&quot;">​</a></h3><p>当Redis内存使用达到上限（<code>maxmemory</code>）时，需要按策略逐出数据。Redis共提供8种淘汰策略：</p><p><strong>淘汰设置了过期时间的键（volatile-xxx）</strong> ：</p><ul><li><code>volatile-lru</code>：淘汰最近最少使用的键</li><li><code>volatile-lfu</code>：淘汰最不经常使用的键</li><li><code>volatile-ttl</code>：淘汰将要过期的键</li><li><code>volatile-random</code>：随机淘汰</li></ul><p><strong>淘汰所有键（allkeys-xxx）</strong> ：</p><ul><li><code>allkeys-lru</code>：从所有键中淘汰最近最少使用的</li><li><code>allkeys-lfu</code>：从所有键中淘汰最不经常使用的</li><li><code>allkeys-random</code>：随机淘汰</li></ul><p><strong>不淘汰</strong>：</p><ul><li><code>no-eviction</code>：内存满时写操作报错</li></ul><p><strong>配置示例</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd"># 设置最大内存</span></span>
<span class="line"><span class="__shiki_1t8gfj">CONFIG</span><span class="__shiki_mdbnqw"> SET</span><span class="__shiki_mdbnqw"> maxmemory</span><span class="__shiki_mdbnqw"> 4gb</span></span>
<span class="line"><span class="__shiki_21nrsd"># 启用LRU策略</span></span>
<span class="line"><span class="__shiki_1t8gfj">CONFIG</span><span class="__shiki_mdbnqw"> SET</span><span class="__shiki_mdbnqw"> maxmemory-policy</span><span class="__shiki_mdbnqw"> allkeys-lru</span></span>
<span class="line"><span class="__shiki_21nrsd"># 启用LFU策略</span></span>
<span class="line"><span class="__shiki_1t8gfj">CONFIG</span><span class="__shiki_mdbnqw"> SET</span><span class="__shiki_mdbnqw"> maxmemory-policy</span><span class="__shiki_mdbnqw"> allkeys-lfu</span></span></code></pre></div><p><strong>策略选择建议</strong>：</p><ul><li><strong>LRU</strong>：适用于频繁访问最新数据的场景，如新闻首页缓存</li><li><strong>LFU</strong>：适用于长期缓存热点数据的场景，如电商商品详情页</li><li><strong>TTL</strong>：适用于需要定期更新数据的场景，如用户会话管理</li><li><strong>Random</strong>：适用于对缓存命中率要求不高的场景，一般用于测试环境</li></ul><h3 id="_2-2-数据过期策略" tabindex="-1">2.2 数据过期策略 <a class="header-anchor" href="#_2-2-数据过期策略" aria-label="Permalink to &quot;2.2 数据过期策略&quot;">​</a></h3><p>Redis采用<strong>定期删除 + 惰性删除</strong>的组合策略：</p><ul><li><strong>惰性删除</strong>：只有在访问key时才检查是否过期，对CPU友好，但可能导致过期key积压</li><li><strong>定期删除</strong>：每隔一段时间抽取一批key检查过期，默认每秒扫描10次（<code>hz</code>配置），每次抽20个，若过期比例超25%则循环抽取，最大执行时间25ms</li></ul><p>TTL设置示例：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">SET</span><span class="__shiki_mdbnqw"> user:123</span><span class="__shiki_mdbnqw"> &quot;John Doe&quot;</span><span class="__shiki_mdbnqw"> EXPIRE</span><span class="__shiki_mdbnqw"> user:123</span><span class="__shiki_dzsirb"> 60</span></span></code></pre></div><h2 id="三、持久化机制" tabindex="-1">三、持久化机制 <a class="header-anchor" href="#三、持久化机制" aria-label="Permalink to &quot;三、持久化机制&quot;">​</a></h2><p>Redis提供两种持久化方案解决内存数据库的数据丢失风险。</p><h3 id="_3-1-rdb快照" tabindex="-1">3.1 RDB快照 <a class="header-anchor" href="#_3-1-rdb快照" aria-label="Permalink to &quot;3.1 RDB快照&quot;">​</a></h3><p><strong>原理</strong>：定时将内存数据以二进制格式写入磁盘文件。</p><p><strong>配置示例</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">save</span><span class="__shiki_dzsirb"> 900</span><span class="__shiki_dzsirb"> 1</span><span class="__shiki_21nrsd">    # 900秒内至少1个键被修改则触发RDB</span></span>
<span class="line"><span class="__shiki_1t8gfj">save</span><span class="__shiki_dzsirb"> 300</span><span class="__shiki_dzsirb"> 10</span><span class="__shiki_21nrsd">   # 300秒内至少10个键被修改则触发RDB</span></span></code></pre></div><p><strong>优势</strong>：文件体积小，恢复速度快，适合大规模数据备份。</p><p><strong>局限</strong>：可能丢失最后一次快照后的数据，大数据集时Fork子进程可能导致服务阻塞。</p><h3 id="_3-2-aof日志" tabindex="-1">3.2 AOF日志 <a class="header-anchor" href="#_3-2-aof日志" aria-label="Permalink to &quot;3.2 AOF日志&quot;">​</a></h3><p><strong>原理</strong>：记录所有写操作命令，服务重启时重放日志。</p><p><strong>配置示例</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">appendonly</span><span class="__shiki_mdbnqw"> yes</span></span>
<span class="line"><span class="__shiki_1t8gfj">appendfsync</span><span class="__shiki_mdbnqw"> everysec</span><span class="__shiki_21nrsd">   # 每秒同步一次</span></span></code></pre></div><p><strong>优势</strong>：数据安全性更高（最多丢失1秒数据），日志文件可读性强。</p><p><strong>局限</strong>：文件体积较大，恢复速度较慢。</p><h3 id="_3-3-混合持久化-推荐" tabindex="-1">3.3 混合持久化（推荐） <a class="header-anchor" href="#_3-3-混合持久化-推荐" aria-label="Permalink to &quot;3.3 混合持久化（推荐）&quot;">​</a></h3><p>Redis 4.0版本支持混合持久化，在AOF重写时将RDB快照嵌入AOF头部，兼顾恢复速度与数据完整性。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">aof-use-rdb-preamble</span><span class="__shiki_mdbnqw"> yes</span></span></code></pre></div><p>重启时Redis优先加载AOF恢复数据。这是生产环境的推荐配置。</p><h2 id="四、高可用架构" tabindex="-1">四、高可用架构 <a class="header-anchor" href="#四、高可用架构" aria-label="Permalink to &quot;四、高可用架构&quot;">​</a></h2><p>Redis通过三种递进的架构方案实现不同级别的高可用。</p><h3 id="_4-1-主从复制" tabindex="-1">4.1 主从复制 <a class="header-anchor" href="#_4-1-主从复制" aria-label="Permalink to &quot;4.1 主从复制&quot;">​</a></h3><p><strong>原理</strong>：允许从节点从主节点拷贝完整数据备份，主库可读写，写操作自动同步到从库，从库只读。</p><p><strong>同步机制</strong>：</p><ul><li><strong>全量复制</strong>：slave请求增量同步被拒后，master生成RDB发送，slave清空本地数据加载RDB</li><li><strong>增量复制</strong>：master将RDB期间的命令记入<code>repl_baklog</code>，持续发送给slave</li></ul><p><strong>特点</strong>：提供数据冗余和读写分离，但无法自动故障转移。</p><h3 id="_4-2-哨兵模式-sentinel" tabindex="-1">4.2 哨兵模式（Sentinel） <a class="header-anchor" href="#_4-2-哨兵模式-sentinel" aria-label="Permalink to &quot;4.2 哨兵模式（Sentinel）&quot;">​</a></h3><p><strong>定位</strong>：在主从复制基础上增加自动故障转移功能。</p><p><strong>工作机制</strong>：</p><ol><li><strong>监控</strong>：Sentinel持续监控主节点和从节点状态</li><li><strong>主观下线（SDOWN）</strong> ：单个Sentinel检测到主节点在30秒内无响应</li><li><strong>客观下线（ODOWN）</strong> ：超过<code>quorum</code>数量的Sentinel确认主节点不可达</li><li><strong>领导者选举</strong>：使用Raft算法选举Leader执行故障转移</li><li><strong>故障转移</strong>：Leader根据优先级、复制偏移量等规则从从节点中选出新主节点</li></ol><p><strong>配置示例</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">sentinel</span><span class="__shiki_mdbnqw"> monitor</span><span class="__shiki_mdbnqw"> mymaster</span><span class="__shiki_dzsirb"> 127.0.0.1</span><span class="__shiki_dzsirb"> 6379</span><span class="__shiki_dzsirb"> 2</span></span>
<span class="line"><span class="__shiki_1t8gfj">sentinel</span><span class="__shiki_mdbnqw"> down-after-milliseconds</span><span class="__shiki_mdbnqw"> mymaster</span><span class="__shiki_dzsirb"> 5000</span></span>
<span class="line"><span class="__shiki_1t8gfj">sentinel</span><span class="__shiki_mdbnqw"> failover-timeout</span><span class="__shiki_mdbnqw"> mymaster</span><span class="__shiki_dzsirb"> 10000</span></span></code></pre></div><p><strong>部署建议</strong>：</p><ul><li>至少部署3个Sentinel实例（奇数个，避免脑裂）</li><li>分布在独立物理节点或可用区</li><li><code>quorum</code>通常设为<code>N/2 + 1</code></li><li>调整<code>min-slaves-to-write</code>防止脑裂</li></ul><p><strong>优缺点</strong>：</p><ul><li>优点：自动化容灾、高可用、客户端透明</li><li>缺点：异步复制可能丢失数据、配置维护成本高、存在脑裂风险</li></ul><h3 id="_4-3-cluster集群" tabindex="-1">4.3 Cluster集群 <a class="header-anchor" href="#_4-3-cluster集群" aria-label="Permalink to &quot;4.3 Cluster集群&quot;">​</a></h3><p><strong>定位</strong>：通过分片将数据分布在多个节点上，实现高可用和横向扩展。</p><p><strong>核心机制</strong>：</p><ul><li><strong>数据分片</strong>：16384个哈希槽（0-16383），不同节点管理不同槽</li><li><strong>数据路由</strong>：<code>slot = CRC16(key) % 16384</code>，根据槽找到对应节点</li><li><strong>主从复制</strong>：每个主节点有一个或多个从节点</li><li><strong>故障转移</strong>：主节点故障时从节点自动提升</li></ul><p><strong>配置示例</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">cluster-enabled</span><span class="__shiki_mdbnqw"> yes</span></span>
<span class="line"><span class="__shiki_1t8gfj">cluster-config-file</span><span class="__shiki_mdbnqw"> nodes.conf</span></span>
<span class="line"><span class="__shiki_1t8gfj">cluster-node-timeout</span><span class="__shiki_dzsirb"> 5000</span></span></code></pre></div><p><strong>部署要求</strong>：至少3个主节点构成最小集群。</p><h2 id="五、性能优化" tabindex="-1">五、性能优化 <a class="header-anchor" href="#五、性能优化" aria-label="Permalink to &quot;五、性能优化&quot;">​</a></h2><h3 id="_5-1-连接池" tabindex="-1">5.1 连接池 <a class="header-anchor" href="#_5-1-连接池" aria-label="Permalink to &quot;5.1 连接池&quot;">​</a></h3><p>高并发场景下频繁创建和销毁连接会导致性能下降，使用连接池可复用连接。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1itgoe">from</span><span class="__shiki_140thh"> redis.connection </span><span class="__shiki_1itgoe">import</span><span class="__shiki_140thh"> ConnectionPool</span></span>
<span class="line"><span class="__shiki_140thh">pool </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> ConnectionPool(</span><span class="__shiki_1jdh33">host</span><span class="__shiki_1itgoe">=</span><span class="__shiki_mdbnqw">&#39;localhost&#39;</span><span class="__shiki_140thh">, </span><span class="__shiki_1jdh33">port</span><span class="__shiki_1itgoe">=</span><span class="__shiki_dzsirb">6379</span><span class="__shiki_140thh">, </span><span class="__shiki_1jdh33">db</span><span class="__shiki_1itgoe">=</span><span class="__shiki_dzsirb">0</span><span class="__shiki_140thh">)</span></span>
<span class="line"><span class="__shiki_140thh">r </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> redis.Redis(</span><span class="__shiki_1jdh33">connection_pool</span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh">pool)</span></span></code></pre></div><p>客户端库通常通过连接池优化连接管理。</p><h3 id="_5-2-管道-pipeline" tabindex="-1">5.2 管道（Pipeline） <a class="header-anchor" href="#_5-2-管道-pipeline" aria-label="Permalink to &quot;5.2 管道（Pipeline）&quot;">​</a></h3><p>管道技术将多个命令一次性发送给服务器，减少网络往返次数。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">pipe </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> r.pipeline()</span></span>
<span class="line"><span class="__shiki_140thh">pipe.set(</span><span class="__shiki_mdbnqw">&#39;foo&#39;</span><span class="__shiki_140thh">, </span><span class="__shiki_mdbnqw">&#39;bar&#39;</span><span class="__shiki_140thh">)</span></span>
<span class="line"><span class="__shiki_140thh">pipe.get(</span><span class="__shiki_mdbnqw">&#39;foo&#39;</span><span class="__shiki_140thh">)</span></span>
<span class="line"><span class="__shiki_140thh">result </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> pipe.execute()</span></span></code></pre></div><h3 id="_5-3-批量操作" tabindex="-1">5.3 批量操作 <a class="header-anchor" href="#_5-3-批量操作" aria-label="Permalink to &quot;5.3 批量操作&quot;">​</a></h3><p>使用<code>MSET</code>、<code>MGET</code>等批量命令减少网络往返。</p><h3 id="_5-4-数据结构选择" tabindex="-1">5.4 数据结构选择 <a class="header-anchor" href="#_5-4-数据结构选择" aria-label="Permalink to &quot;5.4 数据结构选择&quot;">​</a></h3><p>选择合适的数据结构可显著减少内存使用：</p><table tabindex="0"><thead><tr><th>数据结构</th><th>适用场景</th></tr></thead><tbody><tr><td>String</td><td>简单键值对、计数器</td></tr><tr><td>Hash</td><td>对象存储、结构化数据</td></tr><tr><td>List</td><td>消息队列、有序数据</td></tr><tr><td>Set</td><td>唯一值、标签系统</td></tr><tr><td>ZSet</td><td>排行榜、带权重数据</td></tr></tbody></table><h3 id="_5-5-避免阻塞操作" tabindex="-1">5.5 避免阻塞操作 <a class="header-anchor" href="#_5-5-避免阻塞操作" aria-label="Permalink to &quot;5.5 避免阻塞操作&quot;">​</a></h3><p>避免使用<code>KEYS</code>等阻塞命令，使用<code>SCAN</code>替代：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">SCAN</span><span class="__shiki_dzsirb"> 0</span><span class="__shiki_mdbnqw"> MATCH</span><span class="__shiki_mdbnqw"> user:</span><span class="__shiki_dzsirb">*</span><span class="__shiki_mdbnqw"> COUNT</span><span class="__shiki_dzsirb"> 100</span></span></code></pre></div><h2 id="六、高级特性" tabindex="-1">六、高级特性 <a class="header-anchor" href="#六、高级特性" aria-label="Permalink to &quot;六、高级特性&quot;">​</a></h2><h3 id="_6-1-事务" tabindex="-1">6.1 事务 <a class="header-anchor" href="#_6-1-事务" aria-label="Permalink to &quot;6.1 事务&quot;">​</a></h3><p>Redis通过<code>MULTI</code>、<code>EXEC</code>、<code>DISCARD</code>、<code>WATCH</code>实现事务功能。</p><p><strong>基本命令</strong>：</p><ul><li><code>WATCH</code>：监视一个或多个键，被修改则事务被打断</li><li><code>MULTI</code>：标记事务块开始</li><li><code>EXEC</code>：执行事务队列中的所有命令</li><li><code>DISCARD</code>：取消事务</li></ul><p><strong>示例</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_140thh"> MULTI</span></span>
<span class="line"><span class="__shiki_1t8gfj">OK</span></span>
<span class="line"><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_140thh"> INCR foo</span></span>
<span class="line"><span class="__shiki_1t8gfj">QUEUED</span></span>
<span class="line"><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_140thh"> INCR bar</span></span>
<span class="line"><span class="__shiki_1t8gfj">QUEUED</span></span>
<span class="line"><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_140thh"> EXEC</span></span></code></pre></div><p><strong>注意</strong>：Redis事务并非关系型数据库中的严格事务，某操作失败时不会回滚。</p><h3 id="_6-2-lua脚本" tabindex="-1">6.2 Lua脚本 <a class="header-anchor" href="#_6-2-lua脚本" aria-label="Permalink to &quot;6.2 Lua脚本&quot;">​</a></h3><p>Lua脚本允许在Redis服务器端执行原子性操作，减少网络开销。</p><p><strong>基本使用</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">EVAL</span><span class="__shiki_mdbnqw"> &quot;return &#39;Hello, scripting!&#39;&quot;</span><span class="__shiki_dzsirb"> 0</span></span></code></pre></div><p><strong>脚本示例</strong>：</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1itgoe">local</span><span class="__shiki_140thh"> key </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> KEYS[</span><span class="__shiki_dzsirb">1</span><span class="__shiki_140thh">]</span></span>
<span class="line"><span class="__shiki_1itgoe">local</span><span class="__shiki_140thh"> value </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> ARGV[</span><span class="__shiki_dzsirb">1</span><span class="__shiki_140thh">]</span></span>
<span class="line"><span class="__shiki_140thh">redis.</span><span class="__shiki_dzsirb">call</span><span class="__shiki_140thh">(</span><span class="__shiki_mdbnqw">&#39;SET&#39;</span><span class="__shiki_140thh">, key, value)</span></span>
<span class="line"><span class="__shiki_1itgoe">return</span><span class="__shiki_140thh"> redis.</span><span class="__shiki_dzsirb">call</span><span class="__shiki_140thh">(</span><span class="__shiki_mdbnqw">&#39;GET&#39;</span><span class="__shiki_140thh">, key)</span></span></code></pre></div><p><strong>最佳实践</strong>：</p><ul><li>优先使用<code>EVALSHA</code>缓存脚本，避免每次传输脚本内容</li><li>避免在Lua中执行耗时操作（如循环大列表）</li><li>使用<code>redis.pcall</code>增强容错性</li><li>做好参数校验和错误处理</li></ul><p><strong>应用场景</strong>：秒杀库存扣减、分布式锁、限流等需要原子性的场景。</p><h3 id="_6-3-发布订阅-pub-sub" tabindex="-1">6.3 发布订阅（Pub/Sub） <a class="header-anchor" href="#_6-3-发布订阅-pub-sub" aria-label="Permalink to &quot;6.3 发布订阅（Pub/Sub）&quot;">​</a></h3><p>Redis的发布订阅是一种消息通信模式，发布者发送消息，订阅者接收消息。</p><p><strong>使用场景</strong>：</p><ul><li>实时通知和事件处理</li><li>聊天应用</li><li>缓存失效信号广播</li><li>UI更新推送</li></ul><p><strong>注意</strong>：Pub/Sub本质是广播系统，每个订阅者都会收到每条消息。如需消息只投递给一个消费者，应使用Stream。</p><h3 id="_6-4-stream-消息队列" tabindex="-1">6.4 Stream（消息队列） <a class="header-anchor" href="#_6-4-stream-消息队列" aria-label="Permalink to &quot;6.4 Stream（消息队列）&quot;">​</a></h3><p>Redis 5.0引入的Stream是一种日志型数据结构，专门用于处理消息流和事件日志。</p><p><strong>核心特性</strong>：</p><ul><li>消息持久化</li><li>消费者组（Consumer Groups）</li><li>ACK确认机制</li></ul><p><strong>基本操作</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd"># 添加消息</span></span>
<span class="line"><span class="__shiki_1t8gfj">XADD</span><span class="__shiki_mdbnqw"> mystream</span><span class="__shiki_dzsirb"> *</span><span class="__shiki_mdbnqw"> field1</span><span class="__shiki_mdbnqw"> value1</span><span class="__shiki_mdbnqw"> field2</span><span class="__shiki_mdbnqw"> value2</span></span>
<span class="line"><span class="__shiki_21nrsd"># 查询消息</span></span>
<span class="line"><span class="__shiki_1t8gfj">XRANGE</span><span class="__shiki_mdbnqw"> mystream</span><span class="__shiki_mdbnqw"> -</span><span class="__shiki_mdbnqw"> +</span><span class="__shiki_mdbnqw"> COUNT</span><span class="__shiki_dzsirb"> 10</span></span></code></pre></div><p><strong>消费者组示例</strong>：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">redis.xgroup_create(</span><span class="__shiki_mdbnqw">&quot;order_stream&quot;</span><span class="__shiki_140thh">, </span><span class="__shiki_mdbnqw">&quot;order_group&quot;</span><span class="__shiki_140thh">, </span><span class="__shiki_1jdh33">id</span><span class="__shiki_1itgoe">=</span><span class="__shiki_mdbnqw">&quot;0&quot;</span><span class="__shiki_140thh">, </span><span class="__shiki_1jdh33">mkstream</span><span class="__shiki_1itgoe">=</span><span class="__shiki_dzsirb">True</span><span class="__shiki_140thh">)</span></span>
<span class="line"><span class="__shiki_140thh">messages </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> redis.xreadgroup(</span><span class="__shiki_mdbnqw">&quot;order_group&quot;</span><span class="__shiki_140thh">, </span><span class="__shiki_mdbnqw">&quot;consumer1&quot;</span><span class="__shiki_140thh">, {</span><span class="__shiki_mdbnqw">&quot;order_stream&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;&gt;&quot;</span><span class="__shiki_140thh">}, </span><span class="__shiki_1jdh33">count</span><span class="__shiki_1itgoe">=</span><span class="__shiki_dzsirb">1</span><span class="__shiki_140thh">, </span><span class="__shiki_1jdh33">block</span><span class="__shiki_1itgoe">=</span><span class="__shiki_dzsirb">0</span><span class="__shiki_140thh">)</span></span></code></pre></div><p><strong>典型场景</strong>：实时日志系统、订单状态追踪、IoT设备数据。</p><h3 id="_6-5-分布式锁" tabindex="-1">6.5 分布式锁 <a class="header-anchor" href="#_6-5-分布式锁" aria-label="Permalink to &quot;6.5 分布式锁&quot;">​</a></h3><p>Redis通过<code>SETNX</code>等命令实现分布式锁。</p><p><strong>基本实现</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">SETNX</span><span class="__shiki_mdbnqw"> lock:resource</span><span class="__shiki_dzsirb"> true</span><span class="__shiki_mdbnqw"> EX</span><span class="__shiki_dzsirb"> 30</span><span class="__shiki_21nrsd">   # 非阻塞加锁</span></span>
<span class="line"><span class="__shiki_1t8gfj">DEL</span><span class="__shiki_mdbnqw"> lock:resource</span><span class="__shiki_21nrsd">                 # 释放锁</span></span></code></pre></div><p><strong>Redisson框架</strong>：</p><ul><li>使用Hash数据结构存储锁信息</li><li>内置锁续期机制（Watchdog），防止锁无法释放</li><li>支持可重入锁、公平锁、读写锁等</li><li>所有操作打包到Lua脚本中原子执行</li></ul><h2 id="七、缓存常见问题与解决方案" tabindex="-1">七、缓存常见问题与解决方案 <a class="header-anchor" href="#七、缓存常见问题与解决方案" aria-label="Permalink to &quot;七、缓存常见问题与解决方案&quot;">​</a></h2><h3 id="_7-1-缓存穿透" tabindex="-1">7.1 缓存穿透 <a class="header-anchor" href="#_7-1-缓存穿透" aria-label="Permalink to &quot;7.1 缓存穿透&quot;">​</a></h3><p><strong>定义</strong>：查询不存在的数据，缓存和数据库均无法命中，每次请求直达数据库。</p><p><strong>根因</strong>：</p><ul><li>恶意攻击：构造大量不存在的ID</li><li>业务Bug：参数校验不严谨</li><li>缓存预热缺失</li></ul><p><strong>解决方案</strong>：</p><ol><li><strong>接口层入参校验</strong>：过滤明显非法的请求</li><li><strong>布隆过滤器</strong>：将有效Key写入布隆过滤器，不存在则直接拦截。某电商平台实践显示穿透率下降82%</li><li><strong>空值缓存</strong>：对查询结果为空的键设置短期缓存（如30秒-5分钟）</li></ol><h3 id="_7-2-缓存击穿" tabindex="-1">7.2 缓存击穿 <a class="header-anchor" href="#_7-2-缓存击穿" aria-label="Permalink to &quot;7.2 缓存击穿&quot;">​</a></h3><p><strong>定义</strong>：热点Key过期失效的瞬间，海量并发请求直接冲击数据库。</p><p><strong>解决方案</strong>：</p><ol><li><strong>永不过期策略</strong>：通过异步线程定期刷新缓存</li><li><strong>分布式锁控制</strong>：只允许一个线程重建缓存，其他线程等待</li><li><strong>逻辑过期方案</strong>：存储数据时附加过期时间戳，临近过期时异步更新</li></ol><h3 id="_7-3-缓存雪崩" tabindex="-1">7.3 缓存雪崩 <a class="header-anchor" href="#_7-3-缓存雪崩" aria-label="Permalink to &quot;7.3 缓存雪崩&quot;">​</a></h3><p><strong>定义</strong>：大量Key在同一时间集中过期，或Redis集群整体宕机。</p><p><strong>解决方案</strong>：</p><ul><li>过期时间随机化，避免集中失效</li><li>Redis集群部署，保证高可用</li><li>限流熔断组件兜底</li></ul><h2 id="八、redis-7-0-新特性" tabindex="-1">八、Redis 7.0+新特性 <a class="header-anchor" href="#八、redis-7-0-新特性" aria-label="Permalink to &quot;八、Redis 7.0+新特性&quot;">​</a></h2><p>Redis 7.0+完成了从“内存缓存”到“一站式多模数据平台”的架构跃迁。</p><h3 id="_8-1-redis-functions" tabindex="-1">8.1 Redis Functions <a class="header-anchor" href="#_8-1-redis-functions" aria-label="Permalink to &quot;8.1 Redis Functions&quot;">​</a></h3><p>替代传统Lua脚本，解决脚本集群兼容性差、无法持久化复用、权限管控弱等痛点。</p><p><strong>核心特性</strong>：</p><ul><li>函数预编译、持久化存储</li><li>全集群自动同步</li><li>细粒度权限控制、函数版本管理</li><li>执行性能较Lua脚本提升40%+</li></ul><h3 id="_8-2-多线程io" tabindex="-1">8.2 多线程IO <a class="header-anchor" href="#_8-2-多线程io" aria-label="Permalink to &quot;8.2 多线程IO&quot;">​</a></h3><p>Redis 7.0+实现读写全链路多线程优化，突破单线程IO瓶颈：</p><ul><li>高并发场景吞吐提升100%+</li><li>延迟降低50%+</li><li>支持IO线程数动态配置</li></ul><h3 id="_8-3-内存管理优化" tabindex="-1">8.3 内存管理优化 <a class="header-anchor" href="#_8-3-内存管理优化" aria-label="Permalink to &quot;8.3 内存管理优化&quot;">​</a></h3><ul><li>用<strong>Listpack</strong>全面替代Ziplist，内存碎片率降低30%+</li><li>升级jemalloc 5.3内存分配器</li></ul><h3 id="_8-4-持久化优化" tabindex="-1">8.4 持久化优化 <a class="header-anchor" href="#_8-4-持久化优化" aria-label="Permalink to &quot;8.4 持久化优化&quot;">​</a></h3><ul><li><strong>AOF增量重写</strong>：磁盘IO降低90%+，CPU占用降低70%+</li><li><strong>AOF多文件分块存储</strong>：备份恢复效率提升10倍+</li></ul><h3 id="_8-5-其他增强" tabindex="-1">8.5 其他增强 <a class="header-anchor" href="#_8-5-其他增强" aria-label="Permalink to &quot;8.5 其他增强&quot;">​</a></h3><ul><li><strong>Sharded Pub/Sub</strong>：分片发布订阅，网络带宽占用降低90%+</li><li><strong>ACL增强</strong>：支持key粒度的权限控制</li></ul><h2 id="九、总结" tabindex="-1">九、总结 <a class="header-anchor" href="#九、总结" aria-label="Permalink to &quot;九、总结&quot;">​</a></h2><p>Redis作为分布式缓存领域的事实标准，其高级特性体系涵盖：</p><table tabindex="0"><thead><tr><th>维度</th><th>关键技术</th></tr></thead><tbody><tr><td>缓存策略</td><td>LRU/LFU/TTL/随机淘汰，8种淘汰策略</td></tr><tr><td>持久化</td><td>RDB快照、AOF日志、混合持久化</td></tr><tr><td>高可用</td><td>主从复制、哨兵模式、Cluster集群</td></tr><tr><td>性能优化</td><td>连接池、管道、批量操作、数据结构优化</td></tr><tr><td>高级特性</td><td>事务、Lua脚本、Pub/Sub、Stream、分布式锁</td></tr><tr><td>版本演进</td><td>Redis 7.0+ Functions、多线程IO、内存优化</td></tr></tbody></table><p>在实际生产中，需根据业务场景合理选择和组合这些特性，构建高性能、高可用的缓存体系。</p>`,155)])])}const g=a(l,[["render",e]]);export{c as __pageData,g as default};
